11	#ifndef CATLASS_COORD_HPP
12	#define CATLASS_COORD_HPP
13	
14	#include "catlass/catlass.hpp"
15	
16	namespace Catlass {
17	
18	/// Statically-sized array specifying Coords within a tensor
19	template <
20	    int RANK_,                 ///< Logical rank of coordinate
21	    class Index_ = uint32_t,   ///< Index type used for each dimension
22	    class LongIndex_ = int64_t ///< Long index type used for linear offsets
23	    >
24	struct Coord {
25	public:
26	    // Number of elements in Coord
27	    static const int RANK = RANK_;
28	
29	    // Index typen used to store elements
30	    using Index = Index_;
31	
32	    // Type used to represent linear offsets
33	    using LongIndex = LongIndex_;
34	
35	    // Default ctor initializes uniformly
36	    CATLASS_HOST_DEVICE constexpr explicit Coord(Index value = Index(0))
37	    {
38	        for (int i = 0; i < RANK; ++i) {
39	            idx[i] = value;
40	        }
41	    }
42	
43	    // Constructs from an array of integers
44	    CATLASS_HOST_DEVICE constexpr Coord(Index const (&idx_)[RANK])
45	    {
46	        for (int i = 0; i < RANK; ++i) {
47	            idx[i] = idx_[i];
48	        }
49	    }
50	
51	    CATLASS_HOST_DEVICE
52	    int Argmin() const
53	    {
54	        return ArgminImpl<1>(0);
55	    }
56	
57	    // Returns the index of the dimension with greatest value
58	    CATLASS_HOST_DEVICE
59	    int Argmax() const
60	    {
61	        return ArgmaxImpl<1>(0);
62	    }
63	
64	    // Returns true if Coord is non-zero
65	    CATLASS_HOST_DEVICE
66	    explicit operator bool() const
67	    {
68	        return AnyImpl<0>();
69	    }
70	
71	    // Return true if Coord is uniformly zero.
72	    CATLASS_HOST_DEVICE
73	    bool operator!() const
74	    {
75	        return !AnyImpl<0>();
76	    }
77	
78	    // Element-wise addition
79	    CATLASS_HOST_DEVICE
80	    Coord operator+(Coord const& b) const
81	    {
82	        Coord c;
83	        AddCoordImpl<0>(c, b);
84	        return c;
85	    }
86	
87	    // Add a scalar to each element
88	    CATLASS_HOST_DEVICE
89	    Coord operator+(const Index val) const
90	    {
91	        Coord c;
92	        AddScalarImpl<0>(c, val);
93	        return c;
94	    }
95	
96	    // Element-wise subtraction
97	    CATLASS_HOST_DEVICE
98	    Coord operator-(Coord const& b) const
99	    {
100	        Coord c;
101	        SubCoordImpl<0>(c, b);
102	        return c;
103	    }
104	
105	    // Subtract a scalar from each element
106	    CATLASS_HOST_DEVICE
107	    Coord operator-(Index const val) const
108	    {
109	        Coord c;
110	        SubScalarImpl<0>(c, val);
111	        return c;
112	    }
113	
114	    // Element-wise multiply
115	    CATLASS_HOST_DEVICE
116	    Coord operator*(Coord const& b) const
117	    {
118	        Coord c;
119	        MulCoordImpl<0>(c, b);
120	        return c;
121	    }
122	
123	    // Element-wise division
124	    CATLASS_HOST_DEVICE
125	    Coord operator/(Coord const& b) const
126	    {
127	        Coord c;
128	        DivCoordImpl<0>(c, b);
129	        return c;
130	    }
131	
132	    // Element-wise mod
133	    CATLASS_HOST_DEVICE
134	    Coord operator%(Coord const& b) const
135	    {
136	        Coord c;
137	        ModCoordImpl<0>(c, b);
138	        return c;
139	    }
140	
141	    // In-place addition
142	    CATLASS_HOST_DEVICE
143	    Coord& operator+=(Coord const& b)
144	    {
145	        PlusEqualImpl<0>(b);
146	        return *this;
147	    }
148	
149	    // In-place equal
150	    CATLASS_HOST_DEVICE
151	    bool operator==(Coord const& b) const
152	    {
153	        return EqualCoordImpl<0>(b);
154	    }
155	
156	    // In-place equal
157	    CATLASS_HOST_DEVICE
158	    bool operator==(Index const val) const
159	    {
160	        return EqualScalarImpl<0>(val);
161	    }
162	
163	    // Member acces operator
164	    CATLASS_HOST_DEVICE
165	    Index& operator[](int dim)
166	    {
167	        return idx[dim];
168	    }
169	
170	    // Member access operator
171	    CATLASS_HOST_DEVICE
172	    Index const& operator[](int dim) const
173	    {
174	        return idx[dim];
175	    }
176	
177	    // Gets the index of a given Coord element
178	    template <int DIM>
179	    CATLASS_HOST_DEVICE Index& At()
180	    {
181	        return idx[DIM];
182	    }
183	
184	    // Access via index; may limit unrolling potential
185	    CATLASS_HOST_DEVICE
186	    Index& At(int dim)
187	    {
188	        return idx[dim];
189	    }
190	
191	    // Gets the index of a given Coord element
192	    template <int DIM>
193	    CATLASS_HOST_DEVICE Index const& At() const
194	    {
195	        return idx[DIM];
196	    }
197	
198	    // Access via index; may limit unrolling potential
199	    CATLASS_HOST_DEVICE
200	    Index const& At(int dim) const
201	    {
202	        return idx[dim];
203	    }
204	
205	    template <int... Is>
206	    CATLASS_HOST_DEVICE auto GetCoordByAxis() const
207	    {
208	        Index idx_[sizeof...(Is)]{idx[Is]...};
209	        return Coord<sizeof...(Is), Index, LongIndex>{idx_};
210	    }
211	
212	    CATLASS_HOST_DEVICE
213	    static Coord Min(Coord const& a, Coord const& b)
214	    {
215	        Coord res;
216	        for (int i = 0; i < RANK; ++i) {
217	            res[i] = a[i] < b[i] ? a[i] : b[i];
218	        }
219	        return res;
220	    }
221	
222	private:
223	    template <int N>
224	    CATLASS_HOST_DEVICE int ArgminImpl(int i) const
225	    {
226	        if constexpr (N == RANK) {
227	            return i;
228	        } else {
229	            return ArgminImpl<N + 1>(idx[N] < idx[i] ? N : i);
230	        }
231	    }
232	
233	    template <int N>
234	    CATLASS_HOST_DEVICE int ArgmaxImpl(int i) const
235	    {
236	        if constexpr (N == RANK) {
237	            return i;
238	        } else {
239	            return ArgmaxImpl<N + 1>(idx[N] > idx[i] ? N : i);
240	        }
241	    }
242	
243	    template <int N>
244	    CATLASS_HOST_DEVICE bool AnyImpl() const
245	    {
246	        if constexpr (N == RANK) {
247	            return false;
248	        } else {
249	            return idx[N] || AnyImpl<N + 1>();
250	        }
251	    }
252	
253	    template <int N>
254	    CATLASS_HOST_DEVICE void AddCoordImpl(Coord& c, Coord const& b) const
255	    {
256	        if constexpr (N < RANK) {
257	            c.idx[N] = idx[N] + b.idx[N];
258	            AddCoordImpl<N + 1>(c, b);
259	        }
260	    }
261	
262	    template <int N>
263	    CATLASS_HOST_DEVICE void AddScalarImpl(Coord& c, Index const val) const
264	    {
265	        if constexpr (N < RANK) {
266	            c.idx[N] = idx[N] + val;
267	            AddScalarImpl<N + 1>(c, val);
268	        }
269	    }
270	
271	    template <int N>
272	    CATLASS_HOST_DEVICE void SubCoordImpl(Coord& c, Coord const& b) const
273	    {
274	        if constexpr (N < RANK) {
275	            c.idx[N] = idx[N] - b.idx[N];
276	            SubCoordImpl<N + 1>(c, b);
277	        }
278	    }
279	
280	    template <int N>
281	    CATLASS_HOST_DEVICE void SubScalarImpl(Coord& c, Index const val) const
282	    {
283	        if constexpr (N < RANK) {
284	            c.idx[N] = idx[N] - val;
285	            SubScalarImpl<N + 1>(c, val);
286	        }
287	    }
288	
289	    template <int N>
290	    CATLASS_HOST_DEVICE void MulCoordImpl(Coord& c, Coord const& b) const
291	    {
292	        if constexpr (N < RANK) {
293	            c.idx[N] = idx[N] * b.idx[N];
294	            MulCoordImpl<N + 1>(c, b);
295	        }
296	    }
297	
298	    template <int N>
299	    CATLASS_HOST_DEVICE void DivCoordImpl(Coord& c, Coord const& b) const
300	    {
301	        if constexpr (N < RANK) {
302	            c.idx[N] = idx[N] / b.idx[N];
303	            DivCoordImpl<N + 1>(c, b);
304	        }
305	    }
306	
307	    template <int N>
308	    CATLASS_HOST_DEVICE void ModCoordImpl(Coord& c, Coord const& b) const
309	    {
310	        if constexpr (N < RANK) {
311	            c.idx[N] = idx[N] % b.idx[N];
312	            ModCoordImpl<N + 1>(c, b);
313	        }
314	    }
315	
316	    template <int N>
317	    CATLASS_HOST_DEVICE void PlusEqualImpl(Coord const& b)
318	    {
319	        if constexpr (N < RANK) {
320	            idx[N] += b.idx[N];
321	            PlusEqualImpl<N + 1>(b);
322	        }
323	    }
324	
325	    template <int N>
326	    CATLASS_HOST_DEVICE bool EqualCoordImpl(Coord const& b) const
327	    {
328	        if constexpr (N == RANK) {
329	            return true;
330	        } else {
331	            return idx[N] == b.idx[N] && EqualCoordImpl<N + 1>(b);
332	        }
333	    }
334	
335	    template <int N>
336	    CATLASS_HOST_DEVICE bool EqualScalarImpl(Index const val) const
337	    {
338	        if constexpr (N == RANK) {
339	            return true;
340	        } else {
341	            return idx[N] == val && EqualScalarImpl<N + 1>(val);
342	        }
343	    }
344	
345	    // Indices
346	    Index idx[RANK];
347	};
348	
349	// Helper to make a 1-element coordinate
350	template <class T>
351	CATLASS_HOST_DEVICE constexpr Coord<1, T> MakeCoord(T dim0)
352	{
353	    T values[1] = {dim0};
354	    return Coord<1, T>(values);
355	}
356	
357	/// Helper to make a 2-element coordinate
358	template <class T>
359	CATLASS_HOST_DEVICE constexpr Coord<2, T> MakeCoord(T dim0, T dim1)
360	{
361	    T values[2] = {dim0, dim1};
362	    return Coord<2, T>(values);
363	}
