23	/// Block swizzling function for Gemms
24	template <uint32_t SwizzleOffset = 1, uint32_t SwizzleDirection = 0>
25	struct GemmIdentityBlockSwizzle {
26	    /// Data members
27	
28	    GemmCoord problemShape;
29	    MatrixCoord tileMN;
30	    MatrixCoord loopsMN;
31	
32	    /// Methods
33	
34	    CATLASS_DEVICE
35	    GemmIdentityBlockSwizzle()
36	    {}
37	
38	    CATLASS_DEVICE
39	    GemmIdentityBlockSwizzle(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
40	        : problemShape(problemShape_), tileMN(tileMN_)
41	    {
42	        loopsMN = CeilDiv(MatrixCoord(problemShape.GetCoordMN()), tileMN);
43	    }
44	
45	    CATLASS_DEVICE
46	    GemmIdentityBlockSwizzle(GemmCoord const& problemShape_, MatrixCoord const& tileMN_, MatrixCoord const& loopsMN_)
47	        : problemShape(problemShape_), tileMN(tileMN_), loopsMN(loopsMN_)
48	    {}
49	
50	    CATLASS_DEVICE
51	    void Update(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
52	    {
53	        problemShape = problemShape_;
54	        tileMN = tileMN_;
55	
56	        loopsMN = CeilDiv(MatrixCoord(problemShape.GetCoordMN()), tileMN);
57	    }
58	
59	    CATLASS_DEVICE
60	    void Update(GemmCoord const& problemShape_, MatrixCoord const& tileMN_, MatrixCoord const& loopsMN_)
61	    {
62	        problemShape = problemShape_;
63	        tileMN = tileMN_;
64	        loopsMN = loopsMN_;
65	    }
66	
67	    CATLASS_DEVICE
68	    uint32_t GetCoreLoops() const
69	    {
70	        return loopsMN.row() * loopsMN.column();
71	    }
72	
73	    CATLASS_DEVICE
74	    uint32_t GetBatchIdx(uint32_t taskIdx)
75	    {
76	        return taskIdx / (GetCoreLoops());
77	    }
78	
79	    CATLASS_DEVICE
80	    GemmCoord GetBlockCoord(uint32_t taskIdx)
81	    {
82	        uint32_t innerIdx = taskIdx % GetCoreLoops();
83	        if constexpr (SwizzleDirection == 0) { // Zn
84	            uint32_t tileBlockLoop = CeilDiv(loopsMN.row(), SwizzleOffset);
85	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMN.column());
86	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMN.column());
87	
88	            uint32_t nRow = SwizzleOffset;
89	            if (tileBlockIdx == tileBlockLoop - 1) {
90	                nRow = loopsMN.row() - SwizzleOffset * tileBlockIdx;
91	            }
92	            uint32_t mIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nRow;
93	            uint32_t nIdx = inTileBlockIdx / nRow;
94	            if (tileBlockIdx % 2 == 1) {
95	                nIdx = loopsMN.column() - nIdx - 1;
96	            }
97	            return GemmCoord{mIdx, nIdx, 0};
98	        } else if constexpr (SwizzleDirection == 1) { // Nz
99	            uint32_t tileBlockLoop = CeilDiv(loopsMN.column(), SwizzleOffset);
100	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMN.row());
101	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMN.row());
102	
103	            uint32_t nCol = SwizzleOffset;
104	            if (tileBlockIdx == tileBlockLoop - 1) {
105	                nCol = loopsMN.column() - SwizzleOffset * tileBlockIdx;
106	            }
107	            uint32_t mIdx = inTileBlockIdx / nCol;
108	            uint32_t nIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
109	            if (tileBlockIdx % 2 == 1) {
110	                mIdx = loopsMN.row() - mIdx - 1;
111	            }
112	            return GemmCoord{mIdx, nIdx, 0};
113	        }
114	    }
115	
116	    CATLASS_DEVICE
117	    GemmCoord GetActualBlockShape(GemmCoord blockCoord)
118	    {
119	        uint32_t mActual =
120	            (blockCoord.m() == (loopsMN.row() - 1)) ? (problemShape.m() - blockCoord.m() * tileMN.row()) : tileMN.row();
121	        uint32_t nActual = (blockCoord.n() == (loopsMN.column() - 1)) ?
122	                               (problemShape.n() - blockCoord.n() * tileMN.column()) :
123	                               tileMN.column();
124	        uint32_t kActual = problemShape.k();
125	        return GemmCoord{mActual, nActual, kActual};
126	    }
127	};
