129	struct DynamicGemmIdentityBlockSwizzle : public GemmIdentityBlockSwizzle<> {
130	    uint32_t swizzleOffset{1};
131	    uint32_t swizzleDirection{0};
132	
133	    CATLASS_DEVICE
134	    DynamicGemmIdentityBlockSwizzle(
135	        GemmCoord const& problemShape_, MatrixCoord const& tileMN_, uint32_t swizzleOffset_, uint32_t swizzleDirection_)
136	        : swizzleOffset(swizzleOffset_),
137	          swizzleDirection(swizzleDirection_),
