150	    CATLASS_DEVICE
151	    void SetSwizzleParams(uint32_t swizzleOffset_, uint32_t swizzleDirection_)
152	    {
153	        swizzleOffset = swizzleOffset_;
154	        swizzleDirection = swizzleDirection_;
155	    }
156	
157	    CATLASS_DEVICE
158	    GemmCoord GetBlockCoord(uint32_t taskIdx)
159	    {
160	        uint32_t innerIdx = taskIdx % GetCoreLoops();
161	        if (swizzleDirection == 0) { // Zn
162	            uint32_t tileBlockLoop = CeilDiv(loopsMN.row(), swizzleOffset);
163	            uint32_t tileBlockIdx = innerIdx / (swizzleOffset * loopsMN.column());
164	            uint32_t inTileBlockIdx = innerIdx % (swizzleOffset * loopsMN.column());
