166	            uint32_t nRow = swizzleOffset;
167	            if (tileBlockIdx == tileBlockLoop - 1) {
168	                nRow = loopsMN.row() - swizzleOffset * tileBlockIdx;
169	            }
170	            uint32_t mIdx = tileBlockIdx * swizzleOffset + inTileBlockIdx % nRow;
