176	        } else { // Nz
177	            uint32_t tileBlockLoop = CeilDiv(loopsMN.column(), swizzleOffset);
178	            uint32_t tileBlockIdx = innerIdx / (swizzleOffset * loopsMN.row());
179	            uint32_t inTileBlockIdx = innerIdx % (swizzleOffset * loopsMN.row());
180	
181	            uint32_t nCol = swizzleOffset;
182	            if (tileBlockIdx == tileBlockLoop - 1) {
183	                nCol = loopsMN.column() - swizzleOffset * tileBlockIdx;
184	            }
185	            uint32_t mIdx = inTileBlockIdx / nCol;
186	            uint32_t nIdx = tileBlockIdx * swizzleOffset + inTileBlockIdx % nCol;
187	            if (tileBlockIdx % 2 == 1) {
188	                mIdx = loopsMN.row() - mIdx - 1;
189	            }
190	            return GemmCoord{mIdx, nIdx, 0};
191	        }
192	    }
193	};
