195	/// Block swizzling function for Splitk Gemms
196	template <uint32_t SwizzleOffset = 1, uint32_t SwizzleDirection = 0>
197	struct SplitkGemmIdentityBlockSwizzle {
198	    /// Data members
199	
200	    GemmCoord problemShape;
201	    GemmCoord tileShape;
202	    GemmCoord loopsMNK;
203	    uint32_t splitkFactor = 1; // splite k dim into virtual cores
204	
205	    /// Methods
206	
207	    CATLASS_DEVICE
208	    SplitkGemmIdentityBlockSwizzle()
209	    {}
210	
211	    CATLASS_DEVICE
212	    SplitkGemmIdentityBlockSwizzle(
213	        GemmCoord const& problemShape_, GemmCoord const& tileShape_, uint32_t splitkFactor_ = 1)
214	        : problemShape(problemShape_), tileShape(tileShape_), splitkFactor(splitkFactor_)
215	    {
216	        loopsMNK = CeilDiv(problemShape, tileShape);
217	    }
218	
219	    CATLASS_DEVICE
220	    uint32_t GetKIdxBySplitkSliceIdx(uint32_t splitkSliceIdx) const
221	    {
222	        if (splitkSliceIdx < loopsMNK.k() % splitkFactor) {
223	            return (loopsMNK.k() / splitkFactor + 1) * splitkSliceIdx;
224	        } else {
225	            return splitkSliceIdx * (loopsMNK.k() / splitkFactor) + loopsMNK.k() % splitkFactor;
226	        }
227	    }
228	
229	    CATLASS_DEVICE
230	    uint32_t GetSplitkSliceIdx(uint32_t taskIdx) const
231	    {
232	        uint32_t mnLoops = loopsMNK.m() * loopsMNK.n();
233	        return taskIdx % GetCoreLoops() / mnLoops;
234	    }
235	
236	    CATLASS_DEVICE
237	    uint32_t GetCoreLoops() const
238	    {
239	        return loopsMNK.m() * loopsMNK.n() * splitkFactor;
240	    }
241	
242	    CATLASS_DEVICE
243	    uint32_t GetBatchIdx(uint32_t taskIdx)
244	    {
245	        return taskIdx / GetCoreLoops();
246	    }
247	
248	    CATLASS_DEVICE
249	    GemmCoord GetBlockCoord(uint32_t taskIdx)
250	    {
251	        uint32_t splitkSliceIdx = GetSplitkSliceIdx(taskIdx);
252	        uint32_t kIdx = GetKIdxBySplitkSliceIdx(splitkSliceIdx);
253	
254	        uint32_t innerIdx = taskIdx % (loopsMNK.m() * loopsMNK.n());
255	        if constexpr (SwizzleDirection == 0) { // Zn
256	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.m(), SwizzleOffset);
257	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.n());
258	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.n());
259	
260	            uint32_t nRow = SwizzleOffset;
261	            if (tileBlockIdx == tileBlockLoop - 1) {
262	                nRow = loopsMNK.m() - SwizzleOffset * tileBlockIdx;
263	            }
264	            uint32_t mIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nRow;
265	            uint32_t nIdx = inTileBlockIdx / nRow;
266	            if (tileBlockIdx % 2 == 1) {
267	                nIdx = loopsMNK.n() - nIdx - 1;
268	            }
269	            return GemmCoord{mIdx, nIdx, kIdx};
270	        } else if constexpr (SwizzleDirection == 1) { // Nz
271	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.n(), SwizzleOffset);
272	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.m());
273	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.m());
274	
275	            uint32_t nCol = SwizzleOffset;
276	            if (tileBlockIdx == tileBlockLoop - 1) {
277	                nCol = loopsMNK.n() - SwizzleOffset * tileBlockIdx;
278	            }
279	            uint32_t mIdx = inTileBlockIdx / nCol;
280	            uint32_t nIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
281	            if (tileBlockIdx % 2 == 1) {
282	                mIdx = loopsMNK.m() - mIdx - 1;
283	            }
284	            return GemmCoord{mIdx, nIdx, kIdx};
285	        }
286	    }
287	
288	    CATLASS_DEVICE
289	    GemmCoord GetActualBlockShape(GemmCoord blockCoord, uint32_t splitkSliceIdx)
290	    {
291	        uint32_t splitkSliceLen;
292	        if (splitkSliceIdx < loopsMNK.k() % splitkFactor) {
293	            splitkSliceLen = (loopsMNK.k() / splitkFactor + 1) * tileShape.k();
294	        } else {
295	            splitkSliceLen = (loopsMNK.k() / splitkFactor) * tileShape.k();
296	        }
297	        uint32_t mActual = (blockCoord.m() == (loopsMNK.m() - 1)) ?
298	                               (problemShape.m() - blockCoord.m() * tileShape.m()) :
299	                               tileShape.m();
300	        uint32_t nActual = (blockCoord.n() == (loopsMNK.n() - 1)) ?
301	                               (problemShape.n() - blockCoord.n() * tileShape.n()) :
302	                               tileShape.n();
303	        uint32_t kActual = (splitkSliceIdx == (splitkFactor - 1)) ?
304	                               (problemShape.k() - blockCoord.k() * tileShape.k()) :
305	                               splitkSliceLen;
306	        return GemmCoord{mActual, nActual, kActual};
307	    }
308	};
