310	/// Block swizzleing function for single core splitk matmul
311	template <uint32_t SwizzleOffset = 1, uint32_t SwizzleDirection = 0>
312	struct SingleCoreSplitkGemmIdentityBlockSwizzle {
313	    /// Data members
314	    static_assert(SwizzleDirection == 0 || SwizzleDirection == 1, "SwizzleDirection only support 0/1");
315	
316	    GemmCoord problemShape;
317	    GemmCoord tileMNK;
318	    GemmCoord loopsMNK;
319	    uint32_t mnLoopRangeStart;
320	    uint32_t mnLoopRangeLen;
321	
322	    /// Methods
323	    CATLASS_DEVICE
324	    SingleCoreSplitkGemmIdentityBlockSwizzle()
325	    {}
326	
327	    /// Methods
328	    CATLASS_DEVICE
329	    SingleCoreSplitkGemmIdentityBlockSwizzle(GemmCoord const& problemShape_, GemmCoord const& l1TileShape)
330	        : problemShape(problemShape_), tileMNK(l1TileShape)
331	    {
332	        loopsMNK = CeilDiv(problemShape, tileMNK);
333	        GetMNLoopRange(AscendC::GetBlockNum(), AscendC::GetBlockIdx());
334	    }
335	
336	    CATLASS_DEVICE
337	    uint32_t GetSingleCoreLoops() const
338	    {
339	        return loopsMNK.k() * mnLoopRangeLen;
340	    }
341	
342	    CATLASS_DEVICE
343	    void GetMNLoopRange(uint32_t coreNum, uint32_t coreIdx)
344	    {
345	        uint32_t mnLoops = loopsMNK.m() * loopsMNK.n();
346	        uint32_t bPerCore = CeilDiv(mnLoops, coreNum);
347	        // the first tmpNum cores process bPerCore blocks
348	        // and the last (coreNum - tmpNum) cores process (bPerCore - 1) blocks
349	        // total mnLoops = bPerCore * tmpNum + (bPerCore - 1) * (coreNum - tmpNum)
350	        uint32_t tmpNum = mnLoops - coreNum * (bPerCore - 1);
351	
352	        mnLoopRangeStart =
353	            (coreIdx < tmpNum) ? (coreIdx * bPerCore) : (tmpNum * bPerCore + (coreIdx - tmpNum) * (bPerCore - 1));
354	        mnLoopRangeLen = (coreIdx < tmpNum) ? bPerCore : (bPerCore - 1);
355	    }
356	
357	    CATLASS_DEVICE
358	    bool IsAtomicAdd(uint32_t loopIdx)
359	    {
360	        uint32_t kIdx = (loopIdx / mnLoopRangeLen);
361	        return kIdx != 0;
362	    }
363	
364	    CATLASS_DEVICE
365	    GemmCoord GetBlockCoord(uint32_t loopIdx)
366	    {
367	        uint32_t kIdx = (loopIdx / mnLoopRangeLen);
368	        // mnLoopIdx
369	        uint32_t innerIdx = mnLoopRangeStart + loopIdx % mnLoopRangeLen;
370	        if constexpr (SwizzleDirection == 0) { // Zn
371	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.m(), SwizzleOffset);
372	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.n());
373	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.n());
374	            uint32_t tailOffset = loopsMNK.m() - (tileBlockLoop - 1) * SwizzleOffset;
375	            uint32_t nRow = SwizzleOffset;
376	
377	            if (tileBlockLoop >= 2 && tileBlockIdx >= tileBlockLoop - 2 && tailOffset <= SwizzleOffset / 2) {
378	                tileBlockLoop = (loopsMNK.m() - tailOffset) / SwizzleOffset;
379	                tileBlockIdx = tileBlockLoop - 1;
380	                nRow = SwizzleOffset + tailOffset;
381	                inTileBlockIdx = innerIdx - SwizzleOffset * loopsMNK.n() * tileBlockIdx;
382	            } else if (tileBlockIdx == tileBlockLoop - 1) {
383	                nRow = loopsMNK.m() - SwizzleOffset * tileBlockIdx;
384	            }
385	
386	            uint32_t nIdx = inTileBlockIdx / nRow;
387	            if (tileBlockIdx % 2 == 1) {
388	                nIdx = loopsMNK.n() - nIdx - 1;
389	            }
390	
391	            uint32_t mIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nRow;
392	            if (nIdx % 2 == 1) {
393	                mIdx = tileBlockIdx * SwizzleOffset + (nRow - inTileBlockIdx % nRow - 1);
394	            }
395	            return GemmCoord{mIdx, nIdx, kIdx};
396	        } else if constexpr (SwizzleDirection == 1) { // Nz
397	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.n(), SwizzleOffset);
398	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.m());
399	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.m());
400	            uint32_t tailOffset = loopsMNK.n() - (tileBlockLoop - 1) * SwizzleOffset;
401	            uint32_t nCol = SwizzleOffset;
402	
403	            if (tileBlockLoop >= 2 && tileBlockIdx >= tileBlockLoop - 2 && tailOffset < SwizzleOffset / 2) {
404	                tileBlockLoop = (loopsMNK.n() - tailOffset) / SwizzleOffset;
405	                tileBlockIdx = tileBlockLoop - 1;
406	                nCol = SwizzleOffset + tailOffset;
407	                inTileBlockIdx = innerIdx - SwizzleOffset * loopsMNK.m() * tileBlockIdx;
408	            } else if (tileBlockIdx == tileBlockLoop - 1) {
409	                nCol = loopsMNK.n() - SwizzleOffset * tileBlockIdx;
410	            }
411	
412	            uint32_t mIdx = inTileBlockIdx / nCol;
413	            if (tileBlockIdx % 2 == 1) {
414	                mIdx = loopsMNK.m() - mIdx - 1;
415	            }
416	
417	            uint32_t nIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
418	            if (mIdx % 2 == 1) {
419	                nIdx = tileBlockIdx * SwizzleOffset + (nCol - inTileBlockIdx % nCol - 1);
420	            }
421	            return GemmCoord{mIdx, nIdx, kIdx};
422	        }
423	    }
424	
425	    CATLASS_DEVICE
426	    GemmCoord GetActualBlockShape(GemmCoord& blockCoord)
427	    {
428	        uint32_t mActual =
429	            (blockCoord.m() == (loopsMNK.m() - 1)) ? (problemShape.m() - blockCoord.m() * tileMNK.m()) : tileMNK.m();
430	        uint32_t nActual =
431	            (blockCoord.n() == (loopsMNK.n() - 1)) ? (problemShape.n() - blockCoord.n() * tileMNK.n()) : tileMNK.n();
432	        uint32_t kActual = (blockCoord.k() == (loopsMNK.k() - 1)) ?
433	                               (problemShape.k() - (loopsMNK.k() - 1) * tileMNK.k()) :
434	                               tileMNK.k();
435	        return GemmCoord{mActual, nActual, kActual};
436	    }
437	};
