514	/// Block swizzling function for Gemms
515	template <uint32_t SwizzleOffset = 1, uint32_t SwizzleDirection = 0>
516	struct GemmIdentityBlockSwizzleL1FullLoad {
517	    /// Data members
518	
519	    GemmCoord problemShape;
520	    MatrixCoord tileMN;
521	    MatrixCoord loopsMN;
522	
523	    uint32_t loopsPerCore;
524	    uint32_t loopsTail;
525	    uint32_t aicCoreNum;
526	
527	    /// Methods
528	
529	    CATLASS_DEVICE
530	    GemmIdentityBlockSwizzleL1FullLoad()
531	    {}
532	
533	    CATLASS_DEVICE
534	    GemmIdentityBlockSwizzleL1FullLoad(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
535	        : problemShape(problemShape_), tileMN(tileMN_)
536	    {
537	        loopsMN = CeilDiv(MatrixCoord(problemShape.GetCoordMN()), tileMN);
538	        uint32_t loopsTotalNum = GetCoreLoops();
539	        aicCoreNum = AscendC::GetBlockNum();
540	        loopsPerCore = loopsTotalNum / aicCoreNum;
541	        loopsTail = loopsTotalNum % aicCoreNum;
542	    }
543	
544	    CATLASS_DEVICE
545	    GemmIdentityBlockSwizzleL1FullLoad(
546	        GemmCoord const& problemShape_, MatrixCoord const& tileMN_, MatrixCoord const& loopsMN_)
547	        : problemShape(problemShape_), tileMN(tileMN_), loopsMN(loopsMN_)
548	    {
549	        uint32_t loopsTotalNum = GetCoreLoops();
550	        aicCoreNum = AscendC::GetBlockNum();
551	        loopsPerCore = loopsTotalNum / aicCoreNum;
552	        loopsTail = loopsTotalNum % aicCoreNum;
553	    }
554	
555	    CATLASS_DEVICE
556	    void Update(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
557	    {
558	        problemShape = problemShape_;
559	        tileMN = tileMN_;
560	        loopsMN = CeilDiv(MatrixCoord(problemShape.GetCoordMN()), tileMN);
561	
562	        uint32_t loopsTotalNum = GetCoreLoops();
563	        aicCoreNum = AscendC::GetBlockNum();
564	        loopsPerCore = loopsTotalNum / aicCoreNum;
565	        loopsTail = loopsTotalNum % aicCoreNum;
566	    }
567	
568	    CATLASS_DEVICE
569	    void Update(GemmCoord const& problemShape_, MatrixCoord const& tileMN_, MatrixCoord const& loopsMN_)
570	    {
571	        problemShape = problemShape_;
572	        tileMN = tileMN_;
573	        loopsMN = loopsMN_;
574	
575	        uint32_t loopsTotalNum = GetCoreLoops();
576	        aicCoreNum = AscendC::GetBlockNum();
577	        loopsPerCore = loopsTotalNum / aicCoreNum;
578	        loopsTail = loopsTotalNum % aicCoreNum;
579	    }
580	
581	    CATLASS_DEVICE
582	    uint32_t GetCoreLoops() const
583	    {
584	        return loopsMN.row() * loopsMN.column();
585	    }
586	
587	    ////// WARNING: current strategy not support GetBatchIdx()
588	
589	    CATLASS_DEVICE
590	    GemmCoord GetBlockCoord(uint32_t taskIdx)
591	    {
592	        // calculate innerIdx from taskIdx
593	        uint32_t CoreIdx = taskIdx % aicCoreNum;
594	        uint32_t innerCoreIdx = taskIdx / aicCoreNum;
595	        uint32_t innerIdx = CoreIdx * loopsPerCore + innerCoreIdx;
596	        if (CoreIdx < loopsTail) {
597	            innerIdx += CoreIdx;
598	        } else {
599	            innerIdx += loopsTail;
600	        }
601	        // calculate block location in swizzle, using innerIdx
602	        if constexpr (SwizzleDirection == 0) { // Zn
603	            uint32_t tileBlockLoop = CeilDiv(loopsMN.row(), SwizzleOffset);
604	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMN.column());
605	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMN.column());
606	
607	            uint32_t nRow = SwizzleOffset;
608	            if (tileBlockIdx == tileBlockLoop - 1) {
609	                nRow = loopsMN.row() - SwizzleOffset * tileBlockIdx;
610	            }
611	            uint32_t mIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nRow;
612	            uint32_t nIdx = inTileBlockIdx / nRow;
613	            if (tileBlockIdx % 2 == 1) {
614	                nIdx = loopsMN.column() - nIdx - 1;
615	            }
616	            return GemmCoord{mIdx, nIdx, 0};
617	        } else if constexpr (SwizzleDirection == 1) { // Nz
618	            uint32_t tileBlockLoop = CeilDiv(loopsMN.column(), SwizzleOffset);
619	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMN.row());
620	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMN.row());
621	
622	            uint32_t nCol = SwizzleOffset;
623	            if (tileBlockIdx == tileBlockLoop - 1) {
624	                nCol = loopsMN.column() - SwizzleOffset * tileBlockIdx;
625	            }
626	            uint32_t mIdx = inTileBlockIdx / nCol;
627	            uint32_t nIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
628	            if (tileBlockIdx % 2 == 1) {
629	                mIdx = loopsMN.row() - mIdx - 1;
630	            }
631	            return GemmCoord{mIdx, nIdx, 0};
632	        }
633	    }
634	
635	    CATLASS_DEVICE
636	    GemmCoord GetActualBlockShape(GemmCoord blockCoord)
637	    {
638	        uint32_t mActual =
639	            (blockCoord.m() == (loopsMN.row() - 1)) ? (problemShape.m() - blockCoord.m() * tileMN.row()) : tileMN.row();
640	        uint32_t nActual = (blockCoord.n() == (loopsMN.column() - 1)) ?
641	                               (problemShape.n() - blockCoord.n() * tileMN.column()) :
642	                               tileMN.column();
643	        uint32_t kActual = problemShape.k();
644	        return GemmCoord{mActual, nActual, kActual};
645	    }
646	};
