719	/// Block swizzling function for TailSplitk Gemms
720	template <uint32_t SwizzleOffset = 1, uint32_t SwizzleDirection = 0>
721	struct TailSplitkGemmIdentityBlockSwizzle {
722	    /// Data members
723	
724	    GemmCoord problemShape;
725	    GemmCoord tileShape;
726	    GemmCoord loopsMNK;
727	    uint32_t coreNum{1};
728	    uint32_t normalBlockNum{1};
729	    uint32_t tailBlockNum{0};
730	    uint32_t splitkFactor{1}; // splite k dim into virtual cores
731	    uint32_t splitkSliceLen{0};
732	
733	    /// Methods
734	
735	    CATLASS_DEVICE
736	    TailSplitkGemmIdentityBlockSwizzle()
737	    {}
738	
739	    CATLASS_DEVICE
740	    TailSplitkGemmIdentityBlockSwizzle(GemmCoord const& problemShape_, GemmCoord const& tileShape_, uint32_t coreNum_)
741	        : problemShape(problemShape_), tileShape(tileShape_), coreNum(coreNum_)
742	    {
743	        loopsMNK = CeilDiv(problemShape, tileShape);
744	        tailBlockNum = loopsMNK.m() * loopsMNK.n() % coreNum;
745	        normalBlockNum = loopsMNK.m() * loopsMNK.n() - tailBlockNum;
746	        if (tailBlockNum > 0) {
747	            splitkFactor = coreNum / tailBlockNum;
748	        }
749	        if (loopsMNK.k() < splitkFactor) {
750	            splitkFactor = loopsMNK.k();
751	        }
752	        splitkSliceLen = loopsMNK.k() / splitkFactor;
753	    }
754	
755	    CATLASS_DEVICE
756	    uint32_t IsTailBlock(uint32_t taskIdx) const
757	    {
758	        uint32_t innerIdx = taskIdx % GetCoreLoops();
759	        return innerIdx >= normalBlockNum;
760	    }
761	
762	    CATLASS_DEVICE
763	    uint32_t GetSplitkFactor() const
764	    {
765	        return splitkFactor;
766	    }
767	
768	    CATLASS_DEVICE
769	    uint32_t GetNormalBlockNum() const
770	    {
771	        return normalBlockNum;
772	    }
773	
774	    CATLASS_DEVICE
775	    uint32_t GetTailBlockNum() const
776	    {
777	        return tailBlockNum;
778	    }
779	
780	    CATLASS_DEVICE
781	    uint32_t GetCoreLoops() const
782	    {
783	        return normalBlockNum + tailBlockNum * splitkFactor;
784	    }
785	
786	    CATLASS_DEVICE
787	    uint32_t GetBatchIdx(uint32_t taskIdx)
788	    {
789	        return taskIdx / GetCoreLoops();
790	    }
791	
792	    CATLASS_DEVICE
793	    GemmCoord GetBlockCoord(uint32_t taskIdx)
794	    {
795	        uint32_t innerIdx = taskIdx % GetCoreLoops();
796	        uint32_t baseBlockIdx = innerIdx;
797	        uint32_t kIdx = 0;
798	        if (innerIdx >= normalBlockNum) {
799	            baseBlockIdx = normalBlockNum + (innerIdx - normalBlockNum) / splitkFactor;
800	            if ((innerIdx - normalBlockNum) % splitkFactor < loopsMNK.k() % splitkFactor) {
801	                kIdx = (innerIdx - normalBlockNum) % splitkFactor * (splitkSliceLen + 1);
802	            } else {
803	                kIdx = (innerIdx - normalBlockNum) % splitkFactor * splitkSliceLen + (loopsMNK.k() % splitkFactor);
804	            }
805	        }
806	        if constexpr (SwizzleDirection == 0) { // Zn
807	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.m(), SwizzleOffset);
808	            uint32_t tileBlockIdx = baseBlockIdx / (SwizzleOffset * loopsMNK.n());
809	            uint32_t inTileBlockIdx = baseBlockIdx % (SwizzleOffset * loopsMNK.n());
810	
811	            uint32_t nRow = SwizzleOffset;
812	            if (tileBlockIdx == tileBlockLoop - 1) {
813	                nRow = loopsMNK.m() - SwizzleOffset * tileBlockIdx;
814	            }
815	            uint32_t mIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nRow;
816	            uint32_t nIdx = inTileBlockIdx / nRow;
817	            if (tileBlockIdx % 2 == 1) {
818	                nIdx = loopsMNK.n() - nIdx - 1;
819	            }
820	            return GemmCoord{mIdx, nIdx, kIdx};
821	        } else if constexpr (SwizzleDirection == 1) { // Nz
822	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.n(), SwizzleOffset);
823	            uint32_t tileBlockIdx = baseBlockIdx / (SwizzleOffset * loopsMNK.m());
824	            uint32_t inTileBlockIdx = baseBlockIdx % (SwizzleOffset * loopsMNK.m());
825	
826	            uint32_t nCol = SwizzleOffset;
827	            if (tileBlockIdx == tileBlockLoop - 1) {
828	                nCol = loopsMNK.n() - SwizzleOffset * tileBlockIdx;
829	            }
830	            uint32_t mIdx = inTileBlockIdx / nCol;
831	            uint32_t nIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
832	            if (tileBlockIdx % 2 == 1) {
833	                mIdx = loopsMNK.m() - mIdx - 1;
834	            }
835	            return GemmCoord{mIdx, nIdx, kIdx};
836	        }
837	    }
838	
839	    CATLASS_DEVICE
840	    GemmCoord GetActualBlockShape(GemmCoord blockCoord, uint32_t taskIdx)
841	    {
842	        uint32_t mActual = (blockCoord.m() == (loopsMNK.m() - 1)) ?
843	                               (problemShape.m() - blockCoord.m() * tileShape.m()) :
844	                               tileShape.m();
845	        uint32_t nActual = (blockCoord.n() == (loopsMNK.n() - 1)) ?
846	                               (problemShape.n() - blockCoord.n() * tileShape.n()) :
847	                               tileShape.n();
848	
849	        uint32_t innerIdx = taskIdx % GetCoreLoops();
850	        uint32_t kActual{0};
851	        if (innerIdx >= normalBlockNum) {
852	            if ((innerIdx - normalBlockNum) % splitkFactor < loopsMNK.k() % splitkFactor) {
853	                kActual = (blockCoord.k() + splitkSliceLen >= loopsMNK.k()) ?
854	                              (problemShape.k() - blockCoord.k() * tileShape.k()) :
855	                              (splitkSliceLen + 1) * tileShape.k();
856	            } else {
857	                kActual = (blockCoord.k() + splitkSliceLen >= loopsMNK.k()) ?
858	                              (problemShape.k() - blockCoord.k() * tileShape.k()) :
859	                              splitkSliceLen * tileShape.k();
860	            }
861	        } else {
862	            kActual = problemShape.k();
863	        }
864	        return GemmCoord{mActual, nActual, kActual};
865	    }
866	};
867	
868	/// Block swizzling function for streamk Gemms
869	template <uint32_t SwizzleOffset = 1, uint32_t SwizzleDirection = 0>
870	struct StreamkGemmIdentityBlockSwizzle {
871	    /// Data members
872	
873	    GemmCoord problemShape;
874	    GemmCoord tileMNK;
875	    GemmCoord loopsMNK;
876	    uint32_t blockDim;
877	    // Represents the number of ordinary blocks.
878	    uint32_t normalBlocks;
879	    // Represents the number of blocks that need to be split according to the Streamk algorithm.
880	    uint32_t streamkBlocks;
881	    // If computing streamk blocks, how many kTile should each core process
882	    uint32_t kTileNumPerCore;
883	    // Since the number of kTiles may not be evenly divisible by the number of cores,
884	    // some cores need to compute one additoinal kTile compared to others
885	    uint32_t kTileRemain;
886	
887	    struct StreamkBlockDec {
888	        // If the current block is a ordinary block, set it to false.
889	        // If it is a streamk block, set it to true.
890	        bool isStreamkBlock{false};
891	        // If the current block is a cross block-meaning it consists partly of the tail k portion of the
892	        // current basic block and partly of the head k portion of the next basic block, set it to true.
893	        bool isCrossBlock{false};
894	
895	        GemmCoord blockCoord;
896	        GemmCoord actualBlockShape;
897	        GemmCoord streamkBlockCoord;
898	        GemmCoord streamkActualBlockShape;
899	    };
900	
901	    /// Methods
902	
903	    CATLASS_DEVICE
904	    StreamkGemmIdentityBlockSwizzle()
905	    {}
906	
907	    CATLASS_DEVICE
908	    StreamkGemmIdentityBlockSwizzle(GemmCoord const& problemShape_, GemmCoord const& tileMNK_, uint32_t blockDim_)
909	        : problemShape(problemShape_), tileMNK(tileMNK_), blockDim(blockDim_)
910	    {
911	        loopsMNK = CeilDiv(problemShape, tileMNK);
912	        streamkBlocks = loopsMNK.m() * loopsMNK.n() % blockDim;
913	        normalBlocks = loopsMNK.m() * loopsMNK.n() - streamkBlocks;
914	        kTileNumPerCore = streamkBlocks * loopsMNK.k() / blockDim;
915	        kTileRemain = streamkBlocks * loopsMNK.k() % blockDim;
916	    }
917	
918	    CATLASS_DEVICE
919	    uint32_t GetCoreLoops() const
920	    {
921	        uint32_t blocksNum = loopsMNK.m() * loopsMNK.n();
922	        uint32_t coreLoops = blocksNum / blockDim * blockDim + min(streamkBlocks * loopsMNK.k(), blockDim);
923	        return coreLoops;
924	    }
925	
926	    CATLASS_DEVICE
927	    GemmCoord GetBlockCoord(uint32_t taskIdx)
928	    {
929	        uint32_t innerIdx = taskIdx % GetCoreLoops();
930	        if constexpr (SwizzleDirection == 0) { // Zn
931	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.m(), SwizzleOffset);
932	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.n());
933	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.n());
934	
935	            uint32_t nRow = SwizzleOffset;
936	            if (tileBlockIdx == tileBlockLoop - 1) {
937	                nRow = loopsMNK.m() - SwizzleOffset * tileBlockIdx;
938	            }
939	            uint32_t mIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nRow;
940	            uint32_t nIdx = inTileBlockIdx / nRow;
941	            if (tileBlockIdx % 2 == 1) {
942	                nIdx = loopsMNK.n() - nIdx - 1;
943	            }
944	            return GemmCoord{mIdx, nIdx, 0};
945	        } else if constexpr (SwizzleDirection == 1) { // Nz
946	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.n(), SwizzleOffset);
947	            uint32_t tileBlockIdx = innerIdx / (SwizzleOffset * loopsMNK.m());
948	            uint32_t inTileBlockIdx = innerIdx % (SwizzleOffset * loopsMNK.m());
949	
950	            uint32_t nCol = SwizzleOffset;
951	            if (tileBlockIdx == tileBlockLoop - 1) {
952	                nCol = loopsMNK.n() - SwizzleOffset * tileBlockIdx;
953	            }
954	            uint32_t mIdx = inTileBlockIdx / nCol;
955	            uint32_t nIdx = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
956	            if (tileBlockIdx % 2 == 1) {
957	                mIdx = loopsMNK.m() - mIdx - 1;
958	            }
959	            return GemmCoord{mIdx, nIdx, 0};
960	        }
961	    }
962	
963	    CATLASS_DEVICE
964	    GemmCoord GetActualBlockShape(GemmCoord blockCoord)
965	    {
966	        uint32_t mActual =
967	            (blockCoord.m() == (loopsMNK.m() - 1)) ? (problemShape.m() - blockCoord.m() * tileMNK.m()) : tileMNK.m();
968	        uint32_t nActual =
969	            (blockCoord.n() == (loopsMNK.n() - 1)) ? (problemShape.n() - blockCoord.n() * tileMNK.n()) : tileMNK.n();
970	        uint32_t kActual = problemShape.k();
971	        return GemmCoord{mActual, nActual, kActual};
972	    }
973	
974	    CATLASS_DEVICE
975	    uint32_t GetStreamkBlockNum()
976	    {
977	        return streamkBlocks;
978	    }
979	
980	    CATLASS_DEVICE
981	    uint32_t GetNormalBlockNum()
982	    {
983	        return normalBlocks;
984	    }
985	
986	    CATLASS_DEVICE
987	    void GetStreamkBlockDec(uint32_t loopIdx, StreamkBlockDec& streamkBlockDec)
988	    {
989	        if (loopIdx < normalBlocks) {
990	            streamkBlockDec.isStreamkBlock = false;
991	            streamkBlockDec.isCrossBlock = false;
992	            streamkBlockDec.blockCoord = GetBlockCoord(loopIdx);
993	            streamkBlockDec.actualBlockShape = GetActualBlockShape(streamkBlockDec.blockCoord);
994	        } else {
995	            streamkBlockDec.isStreamkBlock = true;
996	            uint32_t curKTileNum = kTileNumPerCore;
997	            uint32_t kTileIdx = ((loopIdx - normalBlocks) * kTileNumPerCore + kTileRemain);
998	            if (loopIdx - normalBlocks < kTileRemain) {
999	                curKTileNum += 1;
1000	                kTileIdx = ((loopIdx - normalBlocks) * curKTileNum);
1001	            }
1002	            uint32_t streamkBlockIdx = kTileIdx / loopsMNK.k();
1003	            GemmCoord blockCoordTmp = GetBlockCoord(normalBlocks + streamkBlockIdx);
1004	            streamkBlockDec.blockCoord = GemmCoord{blockCoordTmp.m(), blockCoordTmp.n(), kTileIdx % loopsMNK.k()};
1005	
1006	            uint32_t nextStreamkBlockIdx = (kTileIdx + curKTileNum) / loopsMNK.k();
1007	            streamkBlockDec.isCrossBlock = false;
1008	            GemmCoord actualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.blockCoord);
1009	            if ((kTileIdx % loopsMNK.k() + curKTileNum) * tileMNK.k() > problemShape.k()) {
1010	                streamkBlockDec.actualBlockShape = GemmCoord{
1011	                    actualBlockShapeTmp.m(), actualBlockShapeTmp.n(),
1012	                    problemShape.k() - (kTileIdx % loopsMNK.k()) * tileMNK.k()};
1013	            } else {
1014	                streamkBlockDec.actualBlockShape =
1015	                    GemmCoord{actualBlockShapeTmp.m(), actualBlockShapeTmp.n(), curKTileNum * tileMNK.k()};
1016	            }
1017	            if (kTileIdx % loopsMNK.k() + curKTileNum > loopsMNK.k()) {
1018	                streamkBlockDec.isCrossBlock = true;
1019	                streamkBlockDec.streamkBlockCoord = GetBlockCoord(normalBlocks + nextStreamkBlockIdx);
1020	                GemmCoord streamkActualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.streamkBlockCoord);
1021	                streamkBlockDec.streamkActualBlockShape = GemmCoord{
1022	                    streamkActualBlockShapeTmp.m(), streamkActualBlockShapeTmp.n(),
1023	                    ((kTileIdx + curKTileNum) % loopsMNK.k()) * tileMNK.k()};
1024	            }
1025	        }
1026	    }
1027	
1028	    CATLASS_DEVICE
1029	    uint32_t GetCoreIdx(uint32_t streamkBlockIdx)
1030	    {
1031	        if (streamkBlockIdx * loopsMNK.k() > kTileRemain * (kTileNumPerCore + 1)) {
1032	            return kTileRemain +
1033	                   (streamkBlockIdx * loopsMNK.k() - kTileRemain * (kTileNumPerCore + 1)) / kTileNumPerCore;
1034	        } else {
1035	            return streamkBlockIdx * loopsMNK.k() / (kTileNumPerCore + 1);
1036	        }
1037	    }
1038	
1039	    CATLASS_DEVICE
1040	    bool IsCross(uint32_t streamkBlockIdx)
1041	    {
1042	        // If the head part of the current block and the tail part of the previous block are computed by
1043	        // the same core, return true.
1044	        if (streamkBlockIdx * loopsMNK.k() > kTileRemain * (kTileNumPerCore + 1)) {
1045	            if ((streamkBlockIdx * loopsMNK.k() - kTileRemain * (kTileNumPerCore + 1)) % kTileNumPerCore == 0) {
1046	                return false;
1047	            } else {
1048	                return true;
1049	            }
1050	        } else {
1051	            if ((streamkBlockIdx * loopsMNK.k()) % (kTileNumPerCore + 1) == 0) {
1052	                return false;
1053	            } else {
1054	                return true;
1055	            }
1056	        }
1057	    }
1058	};
1059	
1060	struct DynamicStreamkGemmIdentityBlockSwizzle : public StreamkGemmIdentityBlockSwizzle<> {
1061	    uint32_t swizzleOffset{1};
1062	    uint32_t swizzleDirection{0};
1063	
1064	    CATLASS_DEVICE
1065	    DynamicStreamkGemmIdentityBlockSwizzle(
1066	        GemmCoord const& problemShape_, GemmCoord const& tileShape_, uint32_t coreNum_, uint32_t swizzleOffset_,
1067	        uint32_t swizzleDirection_)
1068	        : swizzleOffset(swizzleOffset_),
1069	          swizzleDirection(swizzleDirection_),
1070	          StreamkGemmIdentityBlockSwizzle<>(problemShape_, tileShape_, coreNum_)
1071	    {}
