1073	    CATLASS_DEVICE
1074	    DynamicStreamkGemmIdentityBlockSwizzle(
1075	        GemmCoord const& problemShape_, GemmCoord const& tileShape_, uint32_t coreNum_)
1076	        : StreamkGemmIdentityBlockSwizzle<>(problemShape_, tileShape_, coreNum_)
1077	    {}
1078	
1079	    CATLASS_DEVICE
1080	    DynamicStreamkGemmIdentityBlockSwizzle()
1081	    {}
1082	
1083	    CATLASS_DEVICE
1084	    void SetSwizzleParams(uint32_t swizzleOffset_, uint32_t swizzleDirection_)
1085	    {
1086	        swizzleOffset = swizzleOffset_;
1087	        swizzleDirection = swizzleDirection_;
1088	    }
1089	
1090	    CATLASS_DEVICE
1091	    void GetStreamkBlockDec(uint32_t loopIdx, StreamkBlockDec& streamkBlockDec)
1092	    {
1093	        if (loopIdx < normalBlocks) {
1094	            streamkBlockDec.isStreamkBlock = false;
1095	            streamkBlockDec.isCrossBlock = false;
1096	            streamkBlockDec.blockCoord = GetBlockCoord(loopIdx);
1097	            streamkBlockDec.actualBlockShape = GetActualBlockShape(streamkBlockDec.blockCoord);
1098	        } else {
1099	            streamkBlockDec.isStreamkBlock = true;
1100	            uint32_t curKTileNum = kTileNumPerCore;
1101	            uint32_t kTileIdx = ((loopIdx - normalBlocks) * kTileNumPerCore + kTileRemain);
1102	            if (loopIdx - normalBlocks < kTileRemain) {
1103	                curKTileNum += 1;
1104	                kTileIdx = ((loopIdx - normalBlocks) * curKTileNum);
1105	            }
1106	            uint32_t streamkBlockIdx = kTileIdx / loopsMNK.k();
1107	            GemmCoord blockCoordTmp = GetBlockCoord(normalBlocks + streamkBlockIdx);
1108	            streamkBlockDec.blockCoord = GemmCoord{blockCoordTmp.m(), blockCoordTmp.n(), kTileIdx % loopsMNK.k()};
1109	
1110	            uint32_t nextStreamkBlockIdx = (kTileIdx + curKTileNum) / loopsMNK.k();
1111	            streamkBlockDec.isCrossBlock = false;
1112	            GemmCoord actualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.blockCoord);
1113	            if ((kTileIdx % loopsMNK.k() + curKTileNum) * tileMNK.k() > problemShape.k()) {
1114	                streamkBlockDec.actualBlockShape = GemmCoord{
1115	                    actualBlockShapeTmp.m(), actualBlockShapeTmp.n(),
1116	                    problemShape.k() - (kTileIdx % loopsMNK.k()) * tileMNK.k()};
1117	            } else {
1118	                streamkBlockDec.actualBlockShape =
1119	                    GemmCoord{actualBlockShapeTmp.m(), actualBlockShapeTmp.n(), curKTileNum * tileMNK.k()};
1120	            }
1121	            if (kTileIdx % loopsMNK.k() + curKTileNum > loopsMNK.k()) {
1122	                streamkBlockDec.isCrossBlock = true;
1123	                streamkBlockDec.streamkBlockCoord = GetBlockCoord(normalBlocks + nextStreamkBlockIdx);
1124	                GemmCoord streamkActualBlockShapeTmp = GetActualBlockShape(streamkBlockDec.streamkBlockCoord);
1125	                streamkBlockDec.streamkActualBlockShape = GemmCoord{
1126	                    streamkActualBlockShapeTmp.m(), streamkActualBlockShapeTmp.n(),
1127	                    ((kTileIdx + curKTileNum) % loopsMNK.k()) * tileMNK.k()};
1128	            }
1129	        }
1130	    }
1131	
1132	    CATLASS_DEVICE
1133	    GemmCoord GetBlockCoord(uint32_t taskIdx)
1134	    {
1135	        uint32_t innerIdx = taskIdx % GetCoreLoops();
1136	        if (swizzleDirection == 0) { // Zn
1137	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.m(), swizzleOffset);
1138	            uint32_t tileBlockIdx = innerIdx / (swizzleOffset * loopsMNK.n());
1139	            uint32_t inTileBlockIdx = innerIdx % (swizzleOffset * loopsMNK.n());
1140	
1141	            uint32_t nRow = swizzleOffset;
1142	            if (tileBlockIdx == tileBlockLoop - 1) {
1143	                nRow = loopsMNK.m() - swizzleOffset * tileBlockIdx;
1144	            }
1145	            uint32_t mIdx = tileBlockIdx * swizzleOffset + inTileBlockIdx % nRow;
1146	            uint32_t nIdx = inTileBlockIdx / nRow;
1147	            if (tileBlockIdx % 2 == 1) {
1148	                nIdx = loopsMNK.n() - nIdx - 1;
1149	            }
1150	            return GemmCoord{mIdx, nIdx, 0};
1151	        } else { // Nz
1152	            uint32_t tileBlockLoop = CeilDiv(loopsMNK.n(), swizzleOffset);
1153	            uint32_t tileBlockIdx = innerIdx / (swizzleOffset * loopsMNK.m());
1154	            uint32_t inTileBlockIdx = innerIdx % (swizzleOffset * loopsMNK.m());
1155	
1156	            uint32_t nCol = swizzleOffset;
1157	            if (tileBlockIdx == tileBlockLoop - 1) {
1158	                nCol = loopsMNK.n() - swizzleOffset * tileBlockIdx;
1159	            }
1160	            uint32_t mIdx = inTileBlockIdx / nCol;
1161	            uint32_t nIdx = tileBlockIdx * swizzleOffset + inTileBlockIdx % nCol;
1162	            if (tileBlockIdx % 2 == 1) {
1163	                mIdx = loopsMNK.m() - mIdx - 1;
1164	            }
1165	            return GemmCoord{mIdx, nIdx, 0};
1166	        }
1167	    }
1168	};
