1170	/**
1171	 * ColumnBlockSwizzle:  split column
1172	 */
1173	struct ColumnBlockSwizzle : public GemmIdentityBlockSwizzle<> {
1174	    uint32_t nBlocks;
1175	    uint32_t mBlocks;
1176	    uint32_t blocksPerCore;
1177	    uint32_t remainder;
1178	    uint32_t coreIdx;
1179	    uint32_t coreNum;
1180	    uint32_t perCoreTailColumns;
1181	    uint32_t tailTaskStartIdx;
1182	
1183	    CATLASS_DEVICE
1184	    ColumnBlockSwizzle()
1185	    {}
1186	
1187	    CATLASS_DEVICE
1188	    ColumnBlockSwizzle(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
1189	        : GemmIdentityBlockSwizzle<>(problemShape_, tileMN_)
1190	    {
1191	        coreNum = AscendC::GetBlockNum();
1192	        coreIdx = AscendC::GetBlockIdx();
1193	        if (AscendC::GetSubBlockNum() != 1) {
1194	            coreIdx /= 2;
1195	        }
1196	
1197	        SplitTask();
1198	    }
1199	
1200	    CATLASS_DEVICE
1201	    void Update(GemmCoord const& problemShape_, MatrixCoord const& tileMN_)
1202	    {
1203	        problemShape = problemShape_;
1204	        tileMN = tileMN_;
1205	
1206	        loopsMN = CeilDiv(MatrixCoord(problemShape.GetCoordMN()), tileMN);
1207	        SplitTask();
1208	    }
1209	
1210	    CATLASS_DEVICE
1211	    void SplitTask()
1212	    {
1213	        nBlocks = loopsMN.column();
1214	        mBlocks = loopsMN.row();
1215	        // 每个核处理平均处理的列block数
1216	        blocksPerCore = problemShape.n() / (coreNum * tileMN.column());
1217	        uint32_t tailColumn = problemShape.n() % (coreNum * tileMN.column());
1218	
1219	        perCoreTailColumns = tailColumn / coreNum;
1220	
1221	        remainder = tailColumn % coreNum;
1222	
1223	        tailTaskStartIdx = blocksPerCore * mBlocks;
1224	    }
1225	
1226	    CATLASS_DEVICE
1227	    uint32_t GetCoreLoops() const
1228	    {
1229	        uint32_t blockPerRowBlock = blocksPerCore;
1230	        if (perCoreTailColumns > 0 || remainder > coreIdx) {
1231	            blockPerRowBlock += 1;
1232	        }
1233	        return mBlocks * blockPerRowBlock;
1234	    }
1235	
1236	    CATLASS_DEVICE
1237	    uint32_t GetIsTail(uint32_t taskIdx) const
1238	    {
1239	        return (taskIdx >= tailTaskStartIdx);
1240	    }
1241	
1242	    CATLASS_DEVICE
1243	    uint32_t GetTailOffset() const
1244	    {
1245	        uint32_t tailOffset = coreIdx * perCoreTailColumns;
1246	        tailOffset += (remainder > coreIdx ? coreIdx : remainder);
1247	        return tailOffset;
1248	    }
1249	
1250	    CATLASS_DEVICE
1251	    GemmCoord GetBlockCoord(uint32_t taskIdx)
1252	    {
1253	        uint32_t mIdx = taskIdx % mBlocks;
1254	        uint32_t columnLocalIdx = taskIdx / mBlocks;
1255	
1256	        uint32_t nIdx;
1257	        if (taskIdx < tailTaskStartIdx) {
1258	            nIdx = blocksPerCore * coreIdx + columnLocalIdx;
1259	        } else {
1260	            nIdx = blocksPerCore * coreNum;
1261	        }
1262	
1263	        return GemmCoord{mIdx, nIdx, 0};
1264	    }
1265	
1266	    /**
1267	     * GetActualBlockShape: 根据 blockCoord 计算实际块形状（重写基类方法）
1268	     */
1269	    CATLASS_DEVICE
1270	    GemmCoord GetActualBlockShape(GemmCoord blockCoord)
1271	    {
1272	        if (blockCoord.n() >= loopsMN.column()) {
1273	            return GemmCoord{0, 0, problemShape.k()};
1274	        }
1275	
1276	        uint32_t mActual =
1277	            (blockCoord.m() == (loopsMN.row() - 1)) ? (problemShape.m() - blockCoord.m() * tileMN.row()) : tileMN.row();
1278	        uint32_t kActual = problemShape.k();
1279	
1280	        uint32_t nActual;
1281	        if (blockCoord.n() < blocksPerCore * coreNum) {
1282	            nActual = tileMN.column();
1283	        } else if (remainder > coreIdx) {
1284	            nActual = perCoreTailColumns + 1;
1285	        } else {
1286	            nActual = perCoreTailColumns;
1287	        }
1288	
1289	        return GemmCoord{mActual, nActual, kActual};
1290	    }
1291	};
